import math
def priority(task, state, a=2.0, b=3.0, cap=3.0, m=2.0, q=5.0, k=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    pressure = 1.0 + state.queue_len / max(q, 1e-6)
    if ratio < 2.0:
        remaining = 2.0 * est - wait
        mean = max(state.mean_est, est, 1e-6)
        if remaining > 0.0:
            urg = math.exp(-remaining / max(k * mean, 1e-6))
        else:
            urg = 1.0
        return tier * task.weight / est * (1.0 + a * pressure * ratio) * urg
    else:
        return tier * task.weight / est * (1.0 + b * min(ratio - 2.0, cap))  # tuned (a=7.36,b=7.71,cap=1.48,m=2.41,q=17.7,k=2.21)

def priority(task, state, c1=1.0, c2=2.0, a=10.0, b=0.5, m=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / est * (1.0 + b * ratio)
    if ratio >= c2:
        return 2e6 + a * ratio + base
    if ratio >= c1:
        return 1e6 + a * ratio + base
    return base  # tuned (c1=1.24,c2=0.713,a=8.73,b=0.187,m=0.292)
